function validate(input) {
  const [date] = input;
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'date must be a string in the form YYYY-MM-DD.';
  const parsed = new Date(date);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== date) return `${date} is not a real calendar date.`;
  if (date < '1000-01-01' || date > '9999-12-30') return 'date must be from 1000-01-01 to 9999-12-30.';
  return null;
}

