function adapt(input, solve, kit) {
  const [date] = input;
  const value = new Date(date);
  if (typeof value.nextDay !== 'function') throw new Error('Dates have no nextDay method yet: assign a function to Date.prototype.nextDay.');
  const before = value.getTime();
  const result = value.nextDay();
  if (typeof result !== 'string') throw new Error(`nextDay() returned ${String(result)}; it should return a string YYYY-MM-DD.`);
  if (value.getTime() !== before) throw new Error('nextDay() must not change the date it is called on.');
  kit.trace(`new Date("${date}").nextDay() returns "${result}"`);
  return result;
}

