Date.prototype.nextDay = function () {
  // Roll the calendar fields over by hand instead of letting Date do it.
  let year = this.getUTCFullYear();
  let month = this.getUTCMonth() + 1;
  let day = this.getUTCDate() + 1;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > lengths[month - 1]) {
    day = 1;
    month++;
  }
  if (month > 12) {
    month = 1;
    year++;
  }
  const two = (number) => (number < 10 ? '0' : '') + number;
  return year + '-' + two(month) + '-' + two(day);
};

