function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const year = size === 'small' ? pick([1000, 1600, 1900, 1999, 2000, 2023, 2024, 2100, 2400, 9999]) : 1000 + Math.floor(rand() * 9000);
  const month = rand() < 0.3 ? pick([2, 12]) : 1 + Math.floor(rand() * 12);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const length = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  let day = rand() < 0.4 ? length - Math.floor(rand() * 2) : 1 + Math.floor(rand() * length);
  if (year === 9999 && month === 12 && day === 31) day = 30;
  const two = (number) => String(number).padStart(2, '0');
  return [`${year}-${two(month)}-${two(day)}`];
}
